import{z as i,x as B,o as E,c as u,q as l,j as n,D as t,d as r,s as o,S as A,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"编排案例与收束","description":"","frontmatter":{"title":"编排案例与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-case-map.md","filePath":"cs/orch-case-map.md","lastUpdated":1791063341000}'),d={name:"cs/orch-case-map.md"};function p(m,e,C,c,D,h){const s=B("Mermaid");return E(),u("div",null,[e[2]||(e[2]=l('<h1 id="编排案例与收束" tabindex="-1">编排案例与收束 <a class="header-anchor" href="#编排案例与收束" aria-label="Permalink to &quot;编排案例与收束&quot;">​</a></h1><div class="epigraph"><p>编排的全部机制可以压成一句话：把意图写成声明，把收敛交给循环，把预算写进每一步。</p><footer>—— 据 Burns et al., Borg, Omega, and Kubernetes, CACM 2016；Verma et al., EuroSys 2015 与 Kubernetes 官方文档整理</footer></div><p><a href="/cs/orch-storage-orchestration">上一课</a>把持久性接进调度与调和，有状态服务也进了循环。本课是「容器编排」的最后一课：先走四类真实负载，看前八课的机制如何被用满、被取舍，再把整门课程收在一根轴上。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机制各在各的课里；缺口是怎样在一类负载上决定用哪些、付哪些代价——像虚拟化课程用三问收束一样，编排也需要一个可执行的判据，而不是「都用 Kubernetes」的一句话。判据要能回答：这负载吃哪些机制的重、哪些机制对它是纯税、不满足时错在哪一层。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四类案例过一遍。<strong>无状态 Web 服务</strong>是机制的全程闭环：调度器按 request 选节点，发布用预算控制换版，发现把 readiness 翻译成流量，压力大了横向扩——四件事全是循环，人只写 spec。<strong>批处理作业</strong>吃的是优先级与超售的红利：任务可抢占、可重跑，request 诚实填写后，集群的超售空间（资源课的差值）由它来填——这是 Borg 从诞生起的老本行，编排对批的价值先于对服务。<strong>有状态服务上编排</strong>（StatefulSet 加持久卷）技术上可行，但要付卷拓扑对调度的约束、有序操作的速度税；「能上」与「该上」是两问，判据在团队对存储系统的运维能力，不在编排的功能列表。<strong>多团队共享集群</strong>吃的是行政合同：配额定账本、RBAC 定边界、网络策略定段内互信——技术机制之外，优先级表与配额分配是组织谈判的产物。</p>',7)),(E(),n(A,null,{default:t(()=>[o(s,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20ST%7B%22%E6%9C%89%E7%8A%B6%E6%80%81%3F%22%7D%0A%20%20ST%20--%3E%7C%22%E6%98%AF%22%7C%20SS%5B%22StatefulSet%20%E5%8A%A0%E5%8D%B7%3A%20%E4%BB%98%E6%8B%93%E6%89%91%E4%B8%8E%E9%A1%BA%E5%BA%8F%E7%A8%8E%22%5D%0A%20%20ST%20--%3E%7C%22%E5%90%A6%22%7C%20BATCH%7B%22%E9%95%BF%E6%97%B6%E5%8F%AF%E9%87%8D%E8%B7%91%3F%22%7D%0A%20%20BATCH%20--%3E%7C%22%E6%98%AF%22%7C%20JP%5B%22%E6%89%B9%E5%A4%84%E7%90%86%3A%20%E5%90%83%E4%BC%98%E5%85%88%E7%BA%A7%E4%B8%8E%E8%B6%85%E5%94%AE%E7%BA%A2%E5%88%A9%22%5D%0A%20%20BATCH%20--%3E%7C%22%E5%90%A6%22%7C%20WEB%5B%22Web%20%E6%9C%8D%E5%8A%A1%3A%20%E8%B0%83%E5%BA%A6%E5%8F%91%E5%B8%83%E5%8F%91%E7%8E%B0%E9%97%AD%E7%8E%AF%22%5D%0A%20%20W%20--%3E%20ORG%7B%22%E5%A4%9A%E5%9B%A2%E9%98%9F%3F%22%7D%0A%20%20ORG%20--%3E%7C%22%E6%98%AF%22%7C%20MT%5B%22%E9%85%8D%E9%A2%9D%20RBAC%20%E7%BD%91%E7%BB%9C%E7%AD%96%E7%95%A5%E5%AE%9A%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：超售就是把「大家不会同时用满」当红利，接下总和大过物理容量的 request。批处理任务能被杀、能重跑，正好当红利的填充者——缺资源时先抢它的，跑完了再还回来。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,[r("四类案例摆开后，课程的骨架自己显形，"),a("strong",null,"每课都是同一组动作的变奏"),r("：声明——把意图写成 spec 与 status 的差；循环——水平触发的 reconcile 消化一切扰动；预算——收敛的速度与失败半径被显式定价。调度器是「把 pod 意图收敛到节点」的循环，预算是过滤与打分；发布是「把版本意图收敛到副本集」，预算是 surge 与 unavailable；发现是「把选择器收敛到端点集」，预算是分片与传播延迟；资源模型是把承诺编译成内核参数，预算是 request 与 limit 的差；配额是组织账本的循环，网络策略是信任边界的循环，存储是容量意图的循环。Burns 等人在 CACM 2016 把 Kubernetes 的遗产归结为这套模式的通用化：它不是一款产品赢了，是「声明式加控制循环」成了分布式系统管理的事实语法——Borg 在封闭集群里验证的写法，变成了所有人在所有集群上共用的语言。")],-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"对照收束：虚拟化课程问「互信、密度、路径」，答案在隔离轴上选点；编排课程问「意图、收敛、预算」，答案在控制循环里选参数。两门课合起来，才是一个集群的完整账本。")],-1)),e[7]||(e[7]=a("p",null,"这三件套在每一课的变奏，拢起来就是同一个循环：",-1)),(E(),n(A,null,{default:t(()=>[o(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20SPEC%5B%22spec%3A%20%E6%84%8F%E5%9B%BE%22%5D%20--%3E%20LOOP%5B%22reconcile%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20STATUS%5B%22status%3A%20%E5%AE%9E%E5%86%B5%22%5D%20--%3E%20LOOP%0A%20%20LOOP%20--%3E%7C%22%E7%AE%97%E5%B7%AE%2C%20%E6%94%B6%E6%95%9B%E5%B7%AE%E8%B7%9D%22%7C%20ACT%5B%22%E6%89%A7%E8%A1%8C%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20BUD%5B%22%E9%A2%84%E7%AE%97%3A%20surge%2Flimit%2F%E5%88%86%E7%89%87%22%5D%20-.%20%22%E7%BA%A6%E6%9D%9F%E9%80%9F%E5%BA%A6%E4%B8%8E%E5%A4%B1%E8%B4%A5%E5%8D%8A%E5%BE%84%22%20.-%20ACT%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=l('<p><span class="marginnote">直觉类比：reconcile 像恒温空调——你只设目标温度（声明 spec），压缩机自己反复启停（循环）把室温拉回目标；它不关心温度为什么变了，只看「现在的值」与「想要的值」的差。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>编排不解决的事要逐一钉住。不解决安全边界：共享内核的信任面问题在安全课程收束过，编排给的是行政面。不解决可观测性：循环收敛得好坏要靠 <a href="/cs/obs-map">可观测性课程</a> 的指标与追踪看见，编排自身只报 status。不解决应用正确性：重试幂等、背压、<a href="/cs/rate-limit-circuit-breaker">限流与熔断</a>，都是应用与流量层的合同，编排只会重启死掉的容器，不会修好逻辑。也不解决容量规划：request 骗小换来的假密度，任何机制都救不回。声明式更不是万能：强顺序、跨对象、带数据迁移的变更，仍要外加流程与工具。</p><p><span class="marginnote">常见误区：初学者容易以为「上了 Kubernetes，应用就自动高可用」。编排只会重启死掉的容器：bug 照样死循环、容量不够照样雪崩、request 骗小照样被杀。高可用是应用层合同（幂等、健康检查、容量诚实），编排只负责把这份合同执行到底。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>判据三问：这负载吃哪些机制的重、哪些是纯税、不满足时错在哪层。</li><li>四案例各得其所：Web 走闭环、批吃超售红利、有状态付拓扑税、多团队靠行政合同。</li><li>全课程一根轴：声明、循环、预算三件套在每一课重复，差别只在收敛的对象与定价的参数。</li><li>Kubernetes 的遗产是模式不是产品：「声明式加控制循环」成为集群管理的事实语法。</li><li>编排不解决安全边界、可观测性、应用正确性与容量规划；越界的期待都会变成事故。</li><li>出处：Burns et al., CACM 2016；Verma et al., EuroSys 2015；Kubernetes 官方文档；据案例实践整理。</li></ul>',6))])}const g=i(d,[["render",p]]);export{f as __pageData,g as default};
